{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project ON tasks(project_id, id)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Keep a slot even while its task belongs elsewhere. Seed current positions on
// migration without changing the order established by earlier versions.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  project_id INTEGER NOT NULL REFERENCES projects(id),
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (project_id, task_id)
);
CREATE INDEX IF NOT EXISTS task_positions_order ON task_positions(project_id, position);
INSERT OR IGNORE INTO task_positions (project_id, task_id, position)
  SELECT project_id, id, position FROM tasks;`);
const projectQuery = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total_count,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed_count
  FROM projects p`;
const listProjects = db.prepare(`${projectQuery} ORDER BY p.id`);
const getProject = db.prepare(`${projectQuery} WHERE p.id = ?`);
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const projectValue = project => ({ ...project, archived: Boolean(project.archived) });
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const getTask = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, ?)`);
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberPosition = db.prepare('INSERT INTO task_positions (project_id, task_id, position) VALUES (?, ?, ?)');
const getPosition = db.prepare('SELECT position FROM task_positions WHERE project_id = ? AND task_id = ?');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updatePriority = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskValue = task => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(join(root, 'public', 'index.html'))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(join(root, 'public', 'app.js'))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(join(root, 'public', 'style.css'))]],
]);

function json(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

// Calendar arithmetic avoids JavaScript Date's timezone and small-year conversions.
function validDueDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function readInput(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') {
      return json(res, 200, { status: 'ok' });
    }
    if (req.method === 'GET' && path === '/api/projects') {
      return json(res, 200, listProjects.all().map(projectValue));
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return json(res, project ? 200 : 404, project ? projectValue(project) : { error: 'Project not found' });
    }
    if (req.method === 'PATCH' && projectMatch) {
      if (!getProject.get(projectMatch[1])) return json(res, 404, { error: 'Project not found' });
      const input = await readInput(req);
      if (input && Object.hasOwn(input, 'default_priority')) {
        if (getProject.get(projectMatch[1]).archived) return json(res, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(res, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        updateDefaultPriority.run(input.default_priority, projectMatch[1]);
        return json(res, 200, projectValue(getProject.get(projectMatch[1])));
      }
      if (input && Object.hasOwn(input, 'name')) {
        if (getProject.get(projectMatch[1]).archived) return json(res, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(res, 400, { error: 'Project name is required' });
        renameProject.run(name, projectMatch[1]);
        return json(res, 200, projectValue(getProject.get(projectMatch[1])));
      }
      if (typeof input?.archived !== 'boolean') {
        return json(res, 400, { error: 'Archive state must be true or false' });
      }
      updateProject.run(Number(input.archived), projectMatch[1]);
      return json(res, 200, projectValue(getProject.get(projectMatch[1])));
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const input = await readInput(req);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(res, 201, projectValue(getProject.get(result.lastInsertRowid)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      if (!getProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) {
        return json(res, 200, listTasks.all(projectId).map(taskValue));
      }
      if (req.method === 'POST' && !taskId) {
        const input = await readInput(req);
        if (getProject.get(projectId).archived) return json(res, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = transaction(() => {
          const position = nextPosition.get(projectId).position;
          const inserted = insertTask.run(projectId, title, getProject.get(projectId).default_priority, position);
          rememberPosition.run(projectId, inserted.lastInsertRowid, position);
          return inserted;
        });
        return json(res, 201, taskValue(getTask.get(projectId, result.lastInsertRowid)));
      }
      if (req.method === 'PATCH' && taskId) {
        if (!getTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const input = await readInput(req);
        if (getProject.get(projectId).archived) return json(res, 409, { error: 'Archived project' });
        if (input && Object.hasOwn(input, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId < 1 || destinationId === Number(projectId)) {
            return json(res, 400, { error: 'Choose another active project' });
          }
          const destination = getProject.get(destinationId);
          if (!destination) return json(res, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(res, 409, { error: 'Archived project' });
          transaction(() => {
            let position = getPosition.get(destinationId, taskId)?.position;
            if (position === undefined) {
              position = nextPosition.get(destinationId).position;
              rememberPosition.run(destinationId, taskId, position);
            }
            moveTask.run(destinationId, position, projectId, taskId);
          });
          return json(res, 200, taskValue(getTask.get(destinationId, taskId)));
        }
        if (input && Object.hasOwn(input, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || (date !== '' && !validDueDate(date))) {
            return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          updateDueDate.run(date, projectId, taskId);
          return json(res, 200, taskValue(getTask.get(projectId, taskId)));
        }
        if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(res, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updatePriority.run(input.priority, projectId, taskId);
          return json(res, 200, taskValue(getTask.get(projectId, taskId)));
        }
        if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(res, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(res, 200, taskValue(getTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') {
          return json(res, 400, { error: 'Completion must be true or false' });
        }
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(res, 200, taskValue(getTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[0] });
        return res.end(asset[1]);
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(res, error.status, { error: error.message });
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'Unable to complete request' });
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
const app = document.querySelector('#app');
// Keep the list view during navigation, but start each page load on Active.
let projectFilter = 'Active';

async function request(path, options) {
  const response = await fetch(path, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Unable to complete request');
  return result;
}

function alertMessage(message) {
  const alert = app.querySelector('[role="alert"]');
  alert.textContent = message;
  alert.hidden = !message;
}

function navigate(path) {
  history.pushState(null, '', path);
  render();
}

// Normalize only search keys; keep saved names and titles untouched.
function searchKey(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, letter => letter.toLowerCase());
}

function validRangeDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function projectRow(project, onUpdate) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const button = document.createElement('button');
  button.textContent = 'Open project';
  button.addEventListener('click', () => navigate(`/projects/${project.id}`));
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed_count}/${project.total_count} completed`;
  const archive = document.createElement('button');
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    alertMessage('');
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      onUpdate(saved);
    } catch (error) {
      if (row.isConnected) alertMessage(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(name, summary, button, archive);
  return row;
}

async function render() {
  const path = location.pathname;
  app.setAttribute('aria-busy', 'true');
  const match = path.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.innerHTML = `<button id="projects">Projects</button><h1></h1>
      <p id="archive-status" hidden>Archived project</p>
      <form>
        <label for="task-title">Task title</label>
        <div class="create-controls">
          <input id="task-title" type="text" autocomplete="off">
          <button type="submit" disabled>Create task</button>
        </div>
      </form>
      <form id="rename-form">
        <label for="new-project-name">New project name</label>
        <div class="create-controls">
          <input id="new-project-name" type="text" autocomplete="off" disabled>
          <button type="submit" disabled>Rename project</button>
        </div>
      </form>
      <p role="alert" hidden></p>
      <div class="task-filter">
        <label for="task-filter">Task filter</label>
        <select id="task-filter">
          <option>All</option><option>Open</option><option>Completed</option>
        </select>
      </div>
      <div class="task-filter">
        <label for="priority-filter">Priority filter</label>
        <select id="priority-filter">
          <option>All</option><option>Low</option><option>Normal</option><option>High</option>
        </select>
      </div>
      <div class="task-filter">
        <label for="default-task-priority">Default task priority</label>
        <select id="default-task-priority" disabled>
          <option>Low</option><option>Normal</option><option>High</option>
        </select>
      </div>
      <form id="due-range-form" class="task-filter">
        <label for="due-from">Due from</label>
        <input id="due-from" type="text" autocomplete="off">
        <label for="due-through">Due through</label>
        <input id="due-through" type="text" autocomplete="off">
        <button type="submit">Apply due range</button>
      </form>
      <form id="task-search-form" class="task-filter">
        <label for="task-search">Task search</label>
        <input id="task-search" type="text" autocomplete="off">
        <button type="submit">Search tasks</button>
      </form>
      <ul id="task-list" aria-label="Tasks"></ul>`;
    app.querySelector('#projects').addEventListener('click', () => navigate('/'));
    const form = app.querySelector('form');
    const input = app.querySelector('input');
    const submit = form.querySelector('button');
    const filter = app.querySelector('#task-filter');
    const priorityFilter = app.querySelector('#priority-filter');
    const defaultPriority = app.querySelector('#default-task-priority');
    const dueRangeForm = app.querySelector('#due-range-form');
    const dueFrom = app.querySelector('#due-from');
    const dueThrough = app.querySelector('#due-through');
    // Draft fields are separate from the applied range so invalid submissions
    // and unsaved input cannot change the visible membership.
    let appliedFrom = '';
    let appliedThrough = '';
    const searchForm = app.querySelector('#task-search-form');
    const searchInput = app.querySelector('#task-search');
    let appliedQuery = '';
    const list = app.querySelector('ul');
    const renameForm = app.querySelector('#rename-form');
    const renameInput = app.querySelector('#new-project-name');
    const renameSubmit = renameForm.querySelector('button');
    const endpoint = `/api/projects/${match[1]}/tasks`;
    let tasks = [];
    let destinations = [];
    let archived = false;
    let savedDefaultPriority = 'Normal';
    defaultPriority.addEventListener('change', async () => {
      if (defaultPriority.disabled) return;
      defaultPriority.disabled = true;
      submit.disabled = true;
      alertMessage('');
      try {
        const project = await request(`/api/projects/${match[1]}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ default_priority: defaultPriority.value }),
        });
        savedDefaultPriority = project.default_priority;
        defaultPriority.value = savedDefaultPriority;
      } catch (error) {
        defaultPriority.value = savedDefaultPriority;
        if (defaultPriority.isConnected) alertMessage(error.message);
      } finally {
        defaultPriority.disabled = archived;
        submit.disabled = archived;
      }
    });
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (renameSubmit.disabled) return;
      const name = renameInput.value.trim();
      if (!name) {
        alertMessage('Project name is required');
        renameInput.focus();
        return;
      }
      renameSubmit.disabled = true;
      alertMessage('');
      try {
        const project = await request(`/api/projects/${match[1]}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!renameForm.isConnected) return;
        app.querySelector('h1').textContent = project.name;
        document.title = `${project.name} · Workboard`;
        renameInput.value = '';
        renameInput.focus();
      } catch (error) {
        if (renameForm.isConnected) alertMessage(error.message);
      } finally {
        renameSubmit.disabled = archived;
      }
    });
    function displayTasks() {
      const visible = tasks.filter(task =>
        (filter.value === 'All' ||
          (filter.value === 'Completed' ? task.completed : !task.completed)) &&
        (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
        searchKey(task.title).includes(appliedQuery) &&
        ((!appliedFrom && !appliedThrough) ||
          (task.due_date && (!appliedFrom || task.due_date >= appliedFrom) &&
            (!appliedThrough || task.due_date <= appliedThrough))));
      list.replaceChildren(...visible.map(task => {
        const row = document.createElement('li');
        row.dataset.testid = 'task-row';
        const title = document.createElement('span');
        title.textContent = task.title;
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = archived;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          alertMessage('');
          try {
            const saved = await request(`${endpoint}/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            if (list.isConnected) displayTasks();
          } catch (error) {
            checkbox.checked = task.completed;
            if (list.isConnected) alertMessage(error.message);
          } finally {
            checkbox.disabled = archived;
          }
        });
        const taskRenameForm = document.createElement('form');
        taskRenameForm.className = 'create-controls';
        const taskRenameInput = document.createElement('input');
        taskRenameInput.type = 'text';
        taskRenameInput.autocomplete = 'off';
        taskRenameInput.setAttribute('aria-label', 'New task title');
        taskRenameInput.disabled = archived;
        const taskRenameSubmit = document.createElement('button');
        taskRenameSubmit.type = 'submit';
        taskRenameSubmit.textContent = 'Rename task';
        taskRenameSubmit.disabled = archived;
        taskRenameForm.addEventListener('submit', async event => {
          event.preventDefault();
          if (taskRenameSubmit.disabled) return;
          const newTitle = taskRenameInput.value.trim();
          if (!newTitle) {
            alertMessage('Task title is required');
            taskRenameInput.focus();
            return;
          }
          taskRenameSubmit.disabled = true;
          alertMessage('');
          try {
            const saved = await request(`${endpoint}/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ title: newTitle }),
            });
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            if (list.isConnected) displayTasks();
          } catch (error) {
            if (list.isConnected) alertMessage(error.message);
          } finally {
            taskRenameSubmit.disabled = archived;
          }
        });
        taskRenameForm.append(taskRenameInput, taskRenameSubmit);
        const priorityLabel = document.createElement('label');
        priorityLabel.textContent = 'Task priority';
        const priority = document.createElement('select');
        priority.setAttribute('aria-label', 'Task priority');
        for (const value of ['Low', 'Normal', 'High']) {
          const option = document.createElement('option');
          option.value = value;
          option.textContent = value;
          priority.append(option);
        }
        priority.value = task.priority;
        priority.disabled = archived;
        priority.addEventListener('change', async () => {
          priority.disabled = true;
          alertMessage('');
          try {
            const saved = await request(`${endpoint}/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ priority: priority.value }),
            });
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            if (list.isConnected) displayTasks();
          } catch (error) {
            priority.value = task.priority;
            if (list.isConnected) alertMessage(error.message);
          } finally {
            priority.disabled = archived;
          }
        });
        priorityLabel.append(priority);
        const dueDateForm = document.createElement('form');
        dueDateForm.className = 'create-controls';
        const dueDateLabel = document.createElement('label');
        dueDateLabel.textContent = 'Task due date';
        const dueDateInput = document.createElement('input');
        dueDateInput.type = 'text';
        dueDateInput.autocomplete = 'off';
        dueDateInput.setAttribute('aria-label', 'Task due date');
        dueDateInput.value = task.due_date || '';
        dueDateInput.disabled = archived;
        dueDateLabel.append(dueDateInput);
        const dueDateSubmit = document.createElement('button');
